) AS (
  VALUES 
    (157::BIGINT, 'No volvería a llevar con ella nunca. No contesta a las dudas. Si tiene dudas de alguna evaluación hagalo el mismo día porque si no, no contesta. Clases super desordenas y los trabajos con indicaciones muy malas'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'cf13eb759cc921af7c5aab2ddd699f6a2c7f32f79ca4b2ae053401d504252523'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Llevé el curso solo por créditos, pero es PÉSIMA. Las clases son desorganizadas, no se sabe qué hay que hacer con los trabajos, no explica temas... No es mala persona, pero me pareció doble moral. Por favor, si usted está aprendiendo inglés, no matricule con ella (y si ya sabe, también).'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-09-01T00:00:00+00:00'::TIMESTAMPTZ, '3ab6e5ebc93d25ec46d249649a186ba6073011c4af74b13ae92d319d6a841721'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es fácil pasar, es solo de hacer todas las evaluaciones pero las clases son como muy dispersas y se llegan a ver temas muy por encima, no se organiza con el tiempo, da instrucciones confusas a veces y no contesta los correos con dudas. Entonces si de verdad busca aprender inglés no la recomiendo'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '35c0d221fe0158893e6b648abe8a813cae0d0f29653cdf0f20ec0e49b601d568'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '860c577a533f7323c2859bd02b680ab5d619de81d161db05d4717c9076ba3f73'::TEXT, ARRAY[545, 2379, 547, 625]::BIGINT[]),
    (157::BIGINT, 'Muy mala profesora, muy desorganizada, no es clara con las instrucciones, sabes que tienes un trabajo o examen para X día pero no sabes con que te va salir. Si tienes como defenderte en inglés pasas facilísimo pero mejor llévelo con otro profesor, mala pronunciación, lo que habla es patua.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Deja trabajos largos']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, 'b85edaa583f8b742cccf510ad4bef322f1e1289483941a8546b11fd16828822f'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'No es mala persona, pero no sabe enseñar, es muy desorganizada y da indicaciones incompletas. El curso no va a ser difícil de pasar pero deja muchas tareas y las clases las puede extender hasta dos horas solo porque no le da tiempo de hacer las actividades. Puede llegar a hacer menos a los alumnos.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ead2e0916b822587506426277b516cdf241b93e2b5a8322ba5e213d7ad148cf1'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Profesora muy desorganizada'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-03-25T00:00:00+00:00'::TIMESTAMPTZ, '441798515ea8c018ebf4b7e22218f44144bbc06d29a960bb904aa36fefeeb07b'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Si pueden matricular con otro profe háganlo, no la recomiendo para alguien que venga empezando en el idioma, se traba mucho, es desorganizada, se confunde, vocaliza muy regular el ingles, se pierde mucho con los estudiantes evaluando a unos la nota de otros u olvidándose de otros.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-02-25T00:00:00+00:00'::TIMESTAMPTZ, '334d45137547f64d02094f912a30dcfaa81591bf096eaa2834f47a728e620d2c'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es super desorganizada, es porfiada, porque le da una instrucción y luego dijo que no dio esa instrucción. Los exámenes los hace mal, con errores de gramática, si eres amable y le caes bien a la profe pasas, pero sino mucho cuidado porque califica mal y te puede perjudicar.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2023-11-22T00:00:00+00:00'::TIMESTAMPTZ, '7bf24a34f89b5c3d4ff74bab6fc4a612c16a628c9c2089bac61c857f581f34a6'::TEXT, ARRAY[545, 2379, 547, 625]::BIGINT[]),
    (157::BIGINT, 'No speak Alemán, Chino o Italiano, por qué la verdad eso es lo que se le entiende a Kennedy'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2023-11-18T00:00:00+00:00'::TIMESTAMPTZ, '47608a751d71a64e081b4a4f082f302b6a3d8ffbdb030d40632a034dbe5093d5'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Es buena gente, pero sus evaluaciones son super malas y los trabajos son muy largos y no tienen mucho sentido, aparte de las indicaciones son super confusas, no matriculen con ella por salud mental, emocional y física.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2023-11-02T00:00:00+00:00'::TIMESTAMPTZ, 'e8328c3e9b9a540ad74e2bfd2dee211c1f9da71c6ce170ed6311a26bb7e8f38e'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Habla en un idioma que no entiendo pero buen live action de los teen titans'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes']::TEXT[], '2022-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'a7ef1501187af452d8ba82c0f82a61ca9fa5e660a3f795a2a7dff51f808c7d07'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'La profe en si es muy buena gente, pero las instrucciones del proyecto son súper confusas. Ella trata de dar calificaciones a los 8 días que se entregan los trabajos, en eso es ordenada. Y si usted sabe inglés DE FIJO LO PASA. Porque sus clases se basan en jugar y ver video de YouTube'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '788726fdde0ba8644c828a693c8a568045c40c90d4a5b1705e2a59104f9ea706'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'La profe es buenagente, solo que las indicaciones de las tareas son muy confusas, deja un proyecto largo, siento que es tontera un trabajo así para una materia así. Nos corregía al participar en clase y eso es bueno, también trataba de que las clases fueran diferentes como con juegos y actividades.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos proyectos grupales']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '3349a75768d06d27a99672e94ee254e2b06d469369736cba8bec8a000b4e2c64'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'MUY MALA PROFE, ella piensa que todos tienen el mismo nivel de ingles y no es clara, todo es demasiado enredado no se le entienden los proyectos y exposicines que deja.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-06-15T00:00:00+00:00'::TIMESTAMPTZ, '3ad5abf7a5c6753745e9bbfabad09edae474a17f735b830c44972b05c26c1873'::TEXT, ARRAY[545, 2379, 547, 625]::BIGINT[]),
    (157::BIGINT, 'Mala profesora, piensa que todos saben inglés y tienen el mismo nivel, no explica nada y califica como si fuera inglés avanzado'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'b8f59ac8f30039cfcc94a6202f6d596ae1efa24532cfdf167592454adc1e8e9d'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'La profesora piensa que todos sus estudiantes tienen excelentes bases en inglés, por lo que es demasiado exigente a la hora de asignar trabajos y calificar. La pronunciación no es la mejor, lo que hace que cueste entenderle lo que dice. Realmente no aprenderá en el curso.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2022-03-11T00:00:00+00:00'::TIMESTAMPTZ, 'd7674923192977498fc99c533663086a5ce598618cf391a7fa92dbc1c74609d3'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Nunca con esta profe, nunca, la señora nunca se equivoca, califica como si uno fuera bilingüe y ella ni las instrucciones de una tarea sabe dar bien. Solo quería pasar su clase para no verla nunca más'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2022-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'eeef3f75c6d566bc317b2888753bd46a7ea17777e6ddd18422bed02a6e525449'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'La profe no es tan mala, es confusa en las asignaciones que deja pero el curso es bastante fácil si se tiene facilidad con el inglés, sino, recomiendo no matricular con ella. Siempre hace que todos los estudiantes participen en clase. Las clases son muy largas. Siempre pasa lista'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-12T00:00:00+00:00'::TIMESTAMPTZ, '14839268ac8c18552f685f07660cbfa024f3dfda5a153e061bcae3a80993730c'::TEXT, ARRAY[625]::BIGINT[]),
    (157::BIGINT, 'La profesora es amable, sin embargo no me gustaron las clases. Deja guías semanales súper largas y también hace que un curso sencillo se vuelva pesado y aburrido.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '0a901bcbabd7adf3e2d9f286824e14250bf399b373bcae1b7d617f69d8192f01'::TEXT, ARRAY[625]::BIGINT[]),
    (157::BIGINT, 'La verdad no la recomiendo. Es muy desordenada y nunca da instrucciones claras en los trabajos a última hora cambia los parámetros de calificación a su manera. Obliga a encender la cámara y muy pocas veces contesta los correos.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'db2b5b13983d04a7f0ad61a34191121199285600922ecfb5ac52ae6a54751e72'::TEXT, ARRAY[625]::BIGINT[]),
    (157::BIGINT, 'Si tiene buena bases en el inglés lo pasa fácil, es una profe bastante desordenada y deja un proyecto largo para final de semestre. Hay que asistir a todas las clases'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-11T00:00:00+00:00'::TIMESTAMPTZ, '7fe4ad0c875810b1662db18ad077ccb0990a82d63cb02c13f048cdeb78d162fc'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'La profe es un desorden, no ayuda, si uno pide ayuda lo manda a las tutorías, no es clara en nada, hace mal los exámenes y no evalúa bien por su desorden, pide cámara toda la clase y es grosera si pueden no matriculen con ella, pésima profesora'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, '06dce60d6fa784c98177e17e1e0a9ed4a1a95464429200d03b9db74363c7bd20'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Si usted tiene buenas bases el curso se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'd6692c439adeaebe74a67c4408b3754b1dcf129a3d1ab7c548794388f28c64d6'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es muy desordenada con todo, deja tareas largas y aburridas todas las semanas, explica solamente lo básico, casi no me quiso revisar el proyecto final por terquedad de ella. Si quiere aprender algo de inglés, NO matricule con esta profesora por favor.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '79c150ca1c44c4a9b7430bb8a848e1a4fc81fb7f5bf1b8d35581440fb8b84a3c'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Una profesora muy desordenada en todo sentido, además los quiz ni siquiera los revisa así que muchas cosas que se tienen correctas las pone malas también obligaba a los estudiantes a encender la cámara'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2021-06-18T00:00:00+00:00'::TIMESTAMPTZ, '3ba77df18bc5e0c173d436d15145085a3822d2e37c75a99c07393f6baa9024ef'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'La profesora es muy buena persona, pero no tan enseñando. La "ninfa del río" no es muy clara con sus clases, en el TecDigital puede llegar a ser un poco desordenada. Si sabe inglés y quiere llevarlo por salir del tiro, puede hacerlo con ella. Si no sabe y quiere aprender, valórese y no lo haga :)'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '84b98d494cd30428eac0f97cda743e4e93d97803165a192b58f66a74200e4d6b'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'USTED QUE ESTÁ LEYENDO ESTO: NO MATRICULE CON ELLA. Quiérase un poquito y lleve inglés con otra/o profe. Explica súper mal, no se le entiende nada, las instrucciones son nada que ver y a veces hasta grosera es si uno no pone cámara o micrófono. Si uno sabe inglés, todo bien o mejor haga suficiencia.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'c1c5f75d1217e0b6f0f80552b5182d1c2fcc282285b0040366d53049355b144f'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'NO MATRICULE CON ELLA, es terrible y si no le cae bien hace hasta lo imposible por bajar puntos, de verdad que es pésima y mala.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-28T00:00:00+00:00'::TIMESTAMPTZ, '2c8c1cbe01d38a3808cd5d07831784196066dd8891bb62fac524a16ff612bb15'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Un desastre total, no sabe enseñar y aparte, desordenada se le queda corto'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-23T00:00:00+00:00'::TIMESTAMPTZ, '73fde9056e950638e99d8f54eea2a9644a02751d3b3fdc2a0b038f3e33f80f16'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'PÉSIMA. NO META CON ELLA. Su falta de profesionalismo solo se puede comparar con lo mal educada que es. Su enseñanza es patéticamente incorrecta en todos los sentidos. NO LO LLEVE CON ELLA. Se pasa por las nalgas la ética y el respeto.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-13T00:00:00+00:00'::TIMESTAMPTZ, '41b9a1a1aa32be402530aa06bd802f0319b1976793211ea8e7d2f7947bcdd502'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es aburrida, sus clases dan pereza y la actitud no ayuda. Se siente superior a los estudiantes e insinúa que entendamos su manera de evaluar sin haberlo explicado.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-07T00:00:00+00:00'::TIMESTAMPTZ, '162cd7df62d0e6f1bcc6128ba87b1c18ccaefe93952df833762f31e646ef7204'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es muy desordenada, se enreda sola y ni sabe bien inglés. Realmente llevé el curso para subir mi ponderado, pero enseña todo mal.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, 'abe0eb0188de2afdb759bbe4696b9c1d4d1bf7276ae4fa6ef4ca7d30eb659da6'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Si no sabe inglés, le recomiendo elegir otr@ profesor@. Si sabe inglés el curso es fácil. Puede ser un poco desordenada pero al principio del semestre ella nos dio todas las fechas de quices y trabajos así que si se guía con eso, no se va a perder. Pregunte con tiempo, no responde inmediato.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, '371fb294ce90fb1bc6d4ae89758e3cc5416f6b100d8cd0580dbc2dcd64680b9b'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Es una profesora de relleno en el TEC, muy desordenada, realmente el que apenas se esta iniciando en Ingles es mejor alejarse de profesoras como ella.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'f782813c5ef744ed69ee0a58e4ff8adbe03379773127e56f59d82f986f430a2c'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, '(Virtual) Hola :) Si pueden matricular con otro profesor háganlo, si no prepárese para que nunca le responda los correos, o les va a responder cosas que nada que ver. Los trabajos son largos y sin sentido, hay que grabar muchos videos grupales, nunca prepara la clase y se atrasa; no califica bien.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-12-04T00:00:00+00:00'::TIMESTAMPTZ, '5cbfe4bd842600be9fed8f7a6c2a91226f2f7d3e32a74bfbbc8e5eeb12641f96'::TEXT, ARRAY[2976]::BIGINT[]),
    (157::BIGINT, 'Si sabe inglés pasa fijo, si no sabe, se le va a complicar, si lo q quiere es aprender mejor matricule con otro profe'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '8812e8f24347efb8991e8d0149fb41620adf2131aaf475c1f248a5322b056ad0'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Desordenada como ella sola, se enreda mucho, deja un montón de tareas (las revisa al azar porque aunque uno sea consiente que le faltó hacer medio trabajo, con suerte que no revise el suyo obtiene 100) no aclara dudas, de ninguna manera te vas a poder contactar con ella MEJOR NO MATRICULE CON ELLA'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '947ccc5bb056742107577a5b580f1b411622cfeae550e741d9d3090e8421b7e3'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Mucho desorden, gran cantidad de trabajos que realmente no acordan con la cantidad de creditos, no deja claras las indicaciones. Suele enredarse con trabajos de otros grupos.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'c77b00fb4a84243bce50e4524097de31d40c96738f57b5ee12c20fb27d926c88'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es regular ni buena ni mala, si tienes dudas nunca te va responder y si responde es algo que no le preguntaste. Los documentos del Tec digital son un despiche, muchas carpetas y desordenadas cuesta encontrar lo que esta pidiendo. En virtual es un desmadre mas que no ayuda la compa.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-10T00:00:00+00:00'::TIMESTAMPTZ, '801de7262486f10619ebd80c37c3a9932987fbd1131438e5d2a6ffd1b5392843'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'La pagina del curso es un despiche, no sabe dar las clases virtuales, las instrucciones que deja de los trabajos otro completo despiche.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'dfeb84534880016c46fde6df03e52bf80198ec592063ca12c7be4a682026e976'::TEXT, ARRAY[625]::BIGINT[]),
    (157::BIGINT, 'Excelente profe, muy organizada'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-03-05T00:00:00+00:00'::TIMESTAMPTZ, 'a5937cfb6bfcd89d5020c93cdecf2ba2bb8db7a968b86752e3e57ecd5acdbd54'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Pasar es super facil, pero pierde notas y es super despistada, si quieren pasar matriculen, pero no es buena profesora'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos exámenes']::TEXT[], '2019-11-19T00:00:00+00:00'::TIMESTAMPTZ, '954497e15f3e39c76043f2460e61fb2953c2de18432718561b40c33b9752698d'::TEXT, ARRAY[541, 3263]::BIGINT[]),
    (157::BIGINT, 'Esta señora no sabe ni donde está parada. Es super desorganizada y no explica nada.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-18T00:00:00+00:00'::TIMESTAMPTZ, '20f184659fde815c646fda6ffde5911914b5e10076c2c7f36c83f621996655ba'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '58dd98a6fa6c951dd032eda02265ec87fba3d3dd09a9ede5955db5f8a6698f99'::TEXT, ARRAY[3021]::BIGINT[]),
    (157::BIGINT, 'No lleve el curso con ella, es muy desordenada y desorganizada'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-06-09T00:00:00+00:00'::TIMESTAMPTZ, '1dee51249fb0499ec3e93c8c7e41db535cb0205ecb286e795cae2ab7fe706cb8'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'La peor profesora. Nunca se le entiende lo que quiere, un desastre con las notas. Le pone malo lo que tiene bueno. Super aburrida. No meta nada con ella'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '44e4cc38de44f26916ba03f85fc17ae32c837dda3e5a149b0e871f3b220cfd63'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Demasiado desordenada para dar las clases y para dar fechas. Si sabe inglés pasa bien, pero ella no explica nada en clase. Prácticamente no se aprende nada'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'd04c46a16d0efa23bef27995a91da81cc837a438bbae1d54304c68acafb7c4cb'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Desordenada con las fechas de las evaluaciones, muchas tareas y participación en clase. Si ya sabe inglés pasa sin mucho esfuerzo.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '82542ed97f222bad7f3842c49d3113d8cc6e122abdda6736c487ffad9673cba8'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Si usted no sabe inglés no matricule con ella, no va a aprender nada y le va a costar. Casi no explica nada y todas las clases son como actividades en grupos o parejas. Es super desordenada con evaluaciones.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '4928af97aac55c9d633a8ee10388586340de934dc2889bb3638e695f5c599dba'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '34d0730710fcb1c6e0a9c40b56906b7c86a5237a533766c98177c166bc2b0dca'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'La profe es agradable y buena persona, pero es desordenada y siempre hace enredos con las fechas de los trabajos porque es poco clara y cambia en último momento. Si ya sabe algo de ingles va a pasar facil, pero si se le dificulta quizá es mejor otra opción. Mucha atención cuando dice fechas'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd3a13a0055094691f8a96d10108ee5e0c29c8d139afcdc10beeb9eb49b34449d'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es muy desordenada con las evaluaciones, olvida las evaluaciones y después lo pone a correr.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-04-25T00:00:00+00:00'::TIMESTAMPTZ, 'b0400ff0ece1939d52c7e3b4dd3fa76dd785ac4f8034f712deb473bce6ad8847'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Por nada del mundo matricule con ella, su pronunciación es terrible y enseña mal a los estudiantes. Ademas, no acepta que se equivoca. Las clases son super aburridas y deja tareas todas las clases, las cuales no ayudan mucho para el aprendizaje del estudiante'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas', 'Clases largas']::TEXT[], '2017-10-29T00:00:00+00:00'::TIMESTAMPTZ, '4249d480b64a0c9a061160cbdbe8ca2130d3c221bab8fb91de07f47f094ac984'::TEXT, ARRAY[625]::BIGINT[]),
    (157::BIGINT, 'Es buena gente y si se sabe inglés se pasa muy fácil. Si no saben inglés y quieren aprender, mejor metan otro profe.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria']::TEXT[], '2017-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'a10f2b06c0301e5dd3f6c74d1d71d771d9ed00846b5b097941e8fabc5d5141dc'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es buena persona, aunque las clases son algo aburridas. Si no sabe inglés, mejor no lo lleve con ella porque hay que estar respondiendo en clase pues esa es la forma en que pasa lista. Los proyectos son algo fáciles aunque algunos implican reunirse. No regaña si uno no responde pero igual.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo']::TEXT[], '2017-06-17T00:00:00+00:00'::TIMESTAMPTZ, '27657ec6d2332af9acdb779eeb4778b40f1b00381e627782cb02a93ed8186a01'::TEXT, ARRAY[549]::BIGINT[]),
    (157::BIGINT, 'No explica nada, las clases son aburridas, usted no aprende nada ahí.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '143b2fa2c79baccc310547482ac58e42db29dcc128c153531214a526ab348b43'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Si le cuesta o no sabe inglés, no lleve el curso con ella. No sabe explicar para quienes no saben, es desordenada, pide muchas tareas en línea como hacer videos. Ella intenta hacer las clases divertidas, pero como no explica, solo lee el material'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '02e0b6c220b703e1dc311340cc697f9741c0160c380c26c7ab21fd325055c4ed'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'La peor. Clases aburridas, parece que le da pereza vivir. Cualquier persona pasa el curso aunque no sepa decir Hello, no se aprende nada y lo más importante es una desordenada, pierde las notas!!! Si llevan con ella guarden todos los quices y examenes.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '52d3fb6a2ebb37cf4ff3c6563cf0c6e68d124d9d1d9c238b66acf240060417ae'::TEXT, ARRAY[625]::BIGINT[]),
    (157::BIGINT, 'Excelente Profesora, explica demasiado bien'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-29T00:00:00+00:00'::TIMESTAMPTZ, '3e7cb79b74d9d9367ca51d548c6c8c35bcc2a9b06e23b10cb13214bec9affedb'::TEXT, ARRAY[545, 2379, 547, 625]::BIGINT[]),
    (157::BIGINT, 'Muy mala! La clase muy aburrida, olvida todo y si le cuesta el idioma la a pasar mal! Examenes raros y con materia no vista. Hasta en CONARE se han quejado de ella!'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '11b58983a19440b96913afb05c4ffb6f6a43283cfcb30885c8361cf2aea6c761'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Da la clase como si tuviera sueño y es solo leer y responder las varas del libro, no se aprende nada. Pasa mandando información porquería que se encuentra en Internet y deja tareas que no son nada claras. Los exámenes son horribles, mete cosas que nunca vio en clase y maltrata hasta a los que saben.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-09-28T00:00:00+00:00'::TIMESTAMPTZ, '73668c3f8344440952f98f42e53c3a331b6bd2e6043b86d86b664f425e6e625b'::TEXT, ARRAY[1170]::BIGINT[]),
    (157::BIGINT, 'La clase se hace demasiado aburrida'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Exámenes retadores']::TEXT[], '2015-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'c4451b15d9f311eb02c992b6aed8a05ee685cbfa47486102944488e444e81ef0'::TEXT, ARRAY[1169]::BIGINT[]),
    (157::BIGINT, 'Pesima profesora,es muy desordenada y jode por todo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-11T00:00:00+00:00'::TIMESTAMPTZ, '098e8571ccd2d8ac44d0c0c8ac4c524ac2c6886ee073a8e08690a67c4ee4e5b2'::TEXT, ARRAY[545, 2379, 547, 625]::BIGINT[]),
    (157::BIGINT, 'Clase Aburrida, quita poco tiempo, hay que guardar TODO, siempre pierde las notas al final de semestre, es muy desordenada'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'b6124a6246a51408fe8d02265d2eb0a32b07c0de76ec56d10e503cc54abbe040'::TEXT, ARRAY[625]::BIGINT[]),
    (157::BIGINT, 'Buena profe, no quita mucho tiempo solo que los labs son algo largos. Si tiene algo de dominio en ingles se saca más de 90'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'a04dcacae32c61f1a72f6bfeacd98e7bea015a983637282d3e93eb4392003bcc'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Pésima hablando inglés, yo lo llevé con ella y la escuché decir cosas como "letter C", terrible pronunciación, no explica bien, vaga, el curso se pasa si ya la persona habla un inglés bueno.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a4f1f25d7553d8879b92894821c91f7041634ceb31f3e934c8f1151eb5a706c4'::TEXT, ARRAY[625]::BIGINT[]),
    (157::BIGINT, 'Pesima profesora, no sabe explicar, examenes super rudos, demasiado vaga... en fin cero recomendada'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '5c78e8ff272c09505ea6ab1700dd789bc9f792180b71bc998677376ddb9f4842'::TEXT, ARRAY[545, 2379, 547, 625]::BIGINT[]),
    (157::BIGINT, 'Calificación no es clara. muy exigente'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-07-14T00:00:00+00:00'::TIMESTAMPTZ, '18f091b344d2721fcffb90e8ab7c84b94f77a896156936b03d6c7a120e3e6a5c'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es bastante desordenada, si le reclamas de algo que ella hizo te acusa y puede afectar en tu nota, no da las instrucciones claras y no respeta la fecha de cronogramas si no te conectas a una reunión no te da tu nota.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2026-06-17T00:00:00+00:00'::TIMESTAMPTZ, '8dd272f8d2c655f83069c597cd0f4c5fbb9ddc54ccb3a3b8b06acfb087ae4105'::TEXT, ARRAY[545]::BIGINT[]),
    (157::BIGINT, 'Es muy desordenada y se estresa por todo, admite que cada uno sabe todo lo que ella sabe y aveces es muy grosera al hablar.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '28abec7f2634011d43cc63f80969aed7924bb164f62e9ee38b5af3013ede6dc3'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Es muy desordenada, a veces no se entiende lo que esta tratando de explicar y como muchos no dominamos el ingles es aun mas confuso. Son clases largas, pero son interactivas asi que no es tan aburrido, uno aprende con ella, pero muy poco'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Pocos exámenes']::TEXT[], '2022-05-06T00:00:00+00:00'::TIMESTAMPTZ, '4a505c8e1d666817b7fe7673682887b778da948bf2510829f440f8f83f14d647'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'Demasiados trabajos, sus exámenes y quiz son muy raros y con poco tiempo, no hay forma exacta de como prepararse para los exámenes, hay que realizar videos todas las semanas, la participación es prácticamente obligatoria y se estresa fácil si llegas a responder mal.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'La participación importa']::TEXT[], '2022-04-26T00:00:00+00:00'::TIMESTAMPTZ, 'c433bef98a372cb3f2ccc4bfc68b36257b4c0147b729610a88270595e8111e8e'::TEXT, ARRAY[539]::BIGINT[]),
    (157::BIGINT, 'No sabe explicar, cree que todos hablamos inglés, se estresa y siempre son actividades grupales video o audios de conversaciones.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2022-03-09T00:00:00+00:00'::TIMESTAMPTZ, 'f1bd6aa7d06505d23e877b028ea23f6b3fd701b2b01c901cec444f77e50d6271'::TEXT, ARRAY[539]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
